import { Logger } from '@nestjs/common';
import { getDocument, listDocumentKeys } from '../../utils/aws/s3.js';

/**
 * An AWS account a business has handed us for measurement.
 */
export class MeteredAccount {
    /**
     * The account the metering role lives in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * The role we assume to read the account.
     * @example "arn:aws:iam::445566778899:role/metering-metering"
     */
    public roleArn: string;
    /**
     * The external id the role's trust policy asks for, when it asks for one.
     */
    public externalId?: string;
    /**
     * The region the business runs the metered workload in.
     * @example "us-east-1"
     */
    public region: string;
}

/**
 * One account a customer has been onboarded into.
 */
export class CustomerAccountEnrollment {
    /**
     * The account the customer is onboarded for.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * Set when the account is stood up for this customer alone. Everything
     * metered in a dedicated account belongs to its customer, no matter what
     * the resource tags claim.
     */
    public dedicated?: boolean;
}

/**
 * The per customer onboarding record a business keeps in its metering bucket,
 * one object per customer, sitting under the registry's
 * {@link MeteringRegistry.customerRecordPrefix}. Only the customers holding a
 * record are billable.
 */
export class CustomerOnboardingRecord {
    private static readonly logger = new Logger(CustomerOnboardingRecord.name);

    public customerId: string;
    public displayName?: string;
    public accounts: Array<CustomerAccountEnrollment>;

    /**
     * Reads every onboarding record kept under the prefix. A record that cannot
     * be read or that names no customer is skipped rather than failing the
     * whole sweep, so one bad object never takes a business' metering down.
     */
    static async loadAll(bucket: string, prefix: string): Promise<Array<CustomerOnboardingRecord>> {
        if (!prefix) {
            return [];
        }
        const keys = await listDocumentKeys(bucket, prefix);
        const records = await Promise.all(
            keys
                .filter((key) => !key.endsWith('/'))
                .map(async (key) => {
                    try {
                        return await getDocument<CustomerOnboardingRecord>(bucket, key);
                    } catch (err) {
                        CustomerOnboardingRecord.logger.error(`Could not read onboarding record ${key}`, err);
                        return undefined;
                    }
                }),
        );
        return records.filter((record) => record && record.customerId && Array.isArray(record.accounts));
    }
}

/**
 * Who a single account's usage may be billed to. Built from the onboarding
 * records, never from resource tags.
 */
export class AccountTenancy {
    /**
     * The customer the account was stood up for, when it belongs to exactly one.
     */
    public dedicatedTo?: string;
    /**
     * Every customer genuinely onboarded for the account, sorted.
     */
    public tenants: Array<string> = [];

    public get isDedicated(): boolean {
        return !!this.dedicatedTo;
    }
}

/**
 * The onboarding record a business keeps in its metering bucket. It is written
 * by the onboarding flow and read by every collector that has to sweep more
 * than one account.
 */
export class MeteringRegistry {
    private static readonly logger = new Logger(MeteringRegistry.name);

    public businessID: string;
    /**
     * Key prefix the per customer onboarding records sit under in the same
     * bucket, one object per customer.
     * @example "onboarding/customers/"
     */
    public customerRecordPrefix: string;
    public accounts: Array<MeteredAccount>;

    static async load(bucket: string, key: string): Promise<MeteringRegistry> {
        return getDocument<MeteringRegistry>(bucket, key);
    }

    /**
     * Loads the onboarding records living beside the account list in the same
     * metering bucket.
     */
    static async loadCustomerRecords(
        registry: MeteringRegistry,
        bucket: string,
    ): Promise<Array<CustomerOnboardingRecord>> {
        return CustomerOnboardingRecord.loadAll(bucket, registry?.customerRecordPrefix);
    }

    /**
     * Works out, per account, which customers may be billed for usage found in
     * it and whether the account belongs to a single customer.
     *
     * An account counts as dedicated only when exactly one customer is
     * onboarded for it and that customer's record says the account is theirs.
     * Anything else is treated as shared, so usage can only reach the customers
     * the tags name.
     */
    static resolveTenancy(customerRecords: Array<CustomerOnboardingRecord>): Record<string, AccountTenancy> {
        const tenancy: Record<string, AccountTenancy> = {};
        const dedicatedClaims: Record<string, Array<string>> = {};
        (customerRecords ?? []).forEach(({ customerId, accounts }) => {
            (accounts ?? []).forEach(({ accountId, dedicated }) => {
                if (!accountId || !customerId) {
                    return;
                }
                if (!tenancy[accountId]) {
                    tenancy[accountId] = new AccountTenancy();
                }
                if (!tenancy[accountId].tenants.includes(customerId)) {
                    tenancy[accountId].tenants.push(customerId);
                }
                if (dedicated) {
                    dedicatedClaims[accountId] = (dedicatedClaims[accountId] ?? []).concat(customerId);
                }
            });
        });
        Object.keys(tenancy).forEach((accountId) => {
            tenancy[accountId].tenants.sort();
            const claims = dedicatedClaims[accountId] ?? [];
            if (claims.length === 1 && tenancy[accountId].tenants.length === 1) {
                [tenancy[accountId].dedicatedTo] = claims;
            } else if (claims.length) {
                MeteringRegistry.logger.warn(
                    `Account ${accountId} is claimed as dedicated by ${claims.join(
                        ', ',
                    )} while onboarded for ${tenancy[accountId].tenants.join(', ')}, metering it as shared`,
                );
            }
        });
        return tenancy;
    }
}
