new_body = '''    /**
     * Sweeps every account the business has onboarded and returns one usage
     * measurement per customer for the dimension being metered.
     *
     * Attribution follows the onboarding records kept beside the account list:
     * - usage found in an account dedicated to a single customer is that
     *   customer's, whatever the instance tags name, including nothing at all;
     * - usage found in a shared account is split evenly between the customers
     *   the instance names that are genuinely onboarded for the account;
     * - anything that cannot be placed on an onboarded customer is dropped.
     */
    async gatherUsage({
        businessID,
        dimensionId,
        registryBucket,
        registryKey,
    }: {
        businessID: string;
        dimensionId: string;
        registryBucket: string;
        registryKey: string;
    }): Promise<Array<StandardMeasurementEntity>> {
        const registry = await MeteringRegistry.load(registryBucket, registryKey);
        const customerRecords = await MeteringRegistry.loadCustomerRecords(registry, registryBucket);
        const tenancy = MeteringRegistry.resolveTenancy(customerRecords);
        const collected: Array<MeteredInstance> = [];
        for (const account of registry.accounts) {
            // eslint-disable-next-line no-await-in-loop
            const instances = await Ec2InstanceDataGathererService.readAccount(account, dimensionId);
            collected.push(...instances);
        }
        Ec2InstanceDataGathererService.logger.log(
            `Metered ${collected.length} instances across ${registry.accounts.length} accounts`,
        );

        // Fractions of an instance owed to each customer, turned into running
        // time only once every instance has been placed, so an evenly split
        // machine never drifts away from the whole it came from.
        const instanceShare: Record<string, number> = {};
        const instanceIds: Record<string, Array<string>> = {};
        collected.forEach((instance) => {
            const owners = Ec2InstanceDataGathererService.resolveOwners(instance, tenancy[instance.accountId]);
            if (!owners.length) {
                Ec2InstanceDataGathererService.logger.warn(
                    `Skipping unplaceable usage for instance ${instance.instanceId} in account ${instance.accountId}`,
                );
                return;
            }
            const share = 1 / owners.length;
            owners.forEach((customerId) => {
                instanceShare[customerId] = (instanceShare[customerId] ?? 0) + share;
                instanceIds[customerId] = (instanceIds[customerId] ?? []).concat(instance.instanceId);
            });
        });

        return Object.keys(instanceShare)
            .sort()
            .map(
                (customerId) =>
                    new StandardMeasurementEntity({
