import { Ec2InstanceDataGathererService, MeteredInstance } from './ec2InstanceDataGatherer.service.js';
import { CustomerOnboardingRecord, MeteringRegistry } from '../../onboarding/entities/meteringAccounts.entity.js';

const RUNNING_TIME_INCREMENT = 0.08333333;

const registry = {
    businessID: 'biz',
    customerRecordPrefix: 'onboarding/customers/',
    accounts: [
        { accountId: 'dedicated-account', roleArn: 'arn:aws:iam::1:role/r', region: 'us-east-1' },
        { accountId: 'shared-account', roleArn: 'arn:aws:iam::2:role/r', region: 'us-east-1' },
        { accountId: 'unonboarded-account', roleArn: 'arn:aws:iam::3:role/r', region: 'us-east-1' },
    ],
} as MeteringRegistry;

const customerRecords = [
    {
        customerId: 'cus_one',
        accounts: [{ accountId: 'dedicated-account', dedicated: true }, { accountId: 'shared-account' }],
    },
    { customerId: 'cus_two', accounts: [{ accountId: 'shared-account' }] },
] as Array<CustomerOnboardingRecord>;

const instance = (accountId: string, instanceId: string, meteringCustomerId?: string): MeteredInstance => ({
    accountId,
    instanceId,
    instanceType: 'm5.large',
    region: 'us-east-1',
    tags: meteringCustomerId === undefined ? {} : { meteringCustomerId },
});

const instances = [
    instance('dedicated-account', 'i-dedicated-untagged'),
    instance('dedicated-account', 'i-dedicated-mistagged', 'cus_two'),
    instance('shared-account', 'i-shared-two-tenants', 'cus_one,cus_two'),
    instance('shared-account', 'i-shared-one-tenant', 'cus_two'),
    instance('shared-account', 'i-shared-untagged'),
    instance('shared-account', 'i-shared-stranger', 'cus_stranger'),
    instance('unonboarded-account', 'i-unonboarded', 'cus_one'),
];

describe('Ec2InstanceDataGathererService', () => {
    beforeEach(() => {
        jest.restoreAllMocks();
        jest.spyOn(MeteringRegistry, 'load').mockResolvedValue(registry);
        jest.spyOn(CustomerOnboardingRecord, 'loadAll').mockResolvedValue(customerRecords);
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        jest.spyOn(Ec2InstanceDataGathererService as any, 'readAccount').mockImplementation(
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            async (account: any) => instances.filter(({ accountId }) => accountId === account.accountId),
        );
    });

    const gather = () =>
        new Ec2InstanceDataGathererService().gatherUsage({
            businessID: 'biz',
            dimensionId: 'dim',
            registryBucket: 'metering-bucket',
            registryKey: 'onboarding/registry.json',
        });

    it('bills a dedicated account to its customer and splits shared machines between real tenants', async () => {
        const measurements = await gather();
        expect(measurements.map(({ customerId }) => customerId)).toEqual(['cus_one', 'cus_two']);
        // Both dedicated machines plus half of the machine shared with cus_two.
        expect(measurements[0].recordValue).toBeCloseTo(2.5 * RUNNING_TIME_INCREMENT, 10);
        expect(measurements[0].metadata.instanceIds).toBe(
            'i-dedicated-mistagged,i-dedicated-untagged,i-shared-two-tenants',
        );
        expect(measurements[0].metadata.instanceCount).toBe(3);
        // Its own shared machine plus half of the machine shared with cus_one.
        expect(measurements[1].recordValue).toBeCloseTo(1.5 * RUNNING_TIME_INCREMENT, 10);
        expect(measurements[1].metadata.instanceIds).toBe('i-shared-one-tenant,i-shared-two-tenants');
        expect(measurements[1].metadata.instanceCount).toBe(2);
    });

    it('keeps unknown and unplaceable usage off the bill', async () => {
        const measurements = await gather();
        const billed = measurements.map(({ metadata }) => metadata.instanceIds).join(',');
        expect(billed).not.toContain('i-shared-untagged');
        expect(billed).not.toContain('i-shared-stranger');
        expect(billed).not.toContain('i-unonboarded');
        expect(measurements.some(({ customerId }) => customerId === 'cus_stranger')).toBe(false);
    });

    it('does not treat an account as dedicated when another customer is onboarded for it', async () => {
        jest.spyOn(CustomerOnboardingRecord, 'loadAll').mockResolvedValue([
            {
                customerId: 'cus_one',
                accounts: [{ accountId: 'dedicated-account', dedicated: true }],
            },
            { customerId: 'cus_two', accounts: [{ accountId: 'dedicated-account' }] },
        ] as Array<CustomerOnboardingRecord>);
        const measurements = await gather();
        // The untagged machine can no longer be placed, only the tagged one counts.
        expect(measurements).toHaveLength(1);
        expect(measurements[0].customerId).toBe('cus_two');
        expect(measurements[0].recordValue).toBeCloseTo(RUNNING_TIME_INCREMENT, 10);
    });
});
